lines=open('R49-p1.jsonl').read().splitlines()
for i,l in enumerate(lines):
    o=json.loads(l)
    if o['segment_id']=='R49-021':
        o['aspect']='effect'; o['quote']='13'
        o['memo']='Tool result 13 repeats after identical grep count command. locus: agent'
    elif o['segment_id']=='R49-037':
        o['aspect']='effect'
        o['quote']="pattern = re.compile(r'eval\\(\"([\\s\\S]*?)\"\\s*;\\s*(?=\\n\\s*/***/)'"
        o['memo']='Regex in uneval.py invalid (multiple repeat), script crashes. locus: agent'
    elif o['segment_id']=='R49-067':
        lines[i]=None; continue
    elif o['segment_id']=='R49-084':
        o['quote']='chrome.scripting.insertCSS({ target: { tabId: tab.id }, css: styles[site],'
    elif o['segment_id']=='R49-086':
        o['quote']='`chrome.tabs.onCreated.addListener` - OK\n`chrome.tabs.onUpdated.addListener` - OK'
    elif o['segment_id']=='R49-089':
        o['quote']='Static validation of /work/run/out found 2 issue(s).'
    lines[i]=json.dumps(o,ensure_ascii=False)
open('R49-p1.jsonl','w').write('\n'.join(l for l in lines if l)+'\n')
EOF
